-- GenDB engine variant Q10-conjunct_permutation: template q10.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  c_custkey,
  c_name,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  c_acctbal,
  n_name,
  c_address,
  c_phone,
  c_comment
FROM customer, orders, lineitem, nation
WHERE
  c_nationkey = n_nationkey
  AND l_returnflag = 'R'
  AND o_orderdate < $1 + INTERVAL '3 MONTH'
  AND o_orderdate >= $1
  AND l_orderkey = o_orderkey
  AND c_custkey = o_custkey
GROUP BY
  c_custkey,
  c_name,
  c_acctbal,
  c_phone,
  n_name,
  c_address,
  c_comment
ORDER BY
  revenue DESC
LIMIT 20
